fn update(scene: &mut GameScene<'_>, time: &FrameTime) {
    let due = (time.fixed_tick / 60).min(5) as i32;
    while scene.counter_value("planted") < due {
        let n = scene.counter_value("planted") + 1;
        scene.spawn_copy("Seed", format!("Seed {n}"), [2.0 * n as f32, 0.5, 0.0]);
        scene.add_to_counter("planted", 1);
    }
}
